package com.clearchoice;
import android.app.*;import android.os.*;import android.content.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
public class GatewayInstrumentation extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();Context c=getTargetContext();android.content.SharedPreferences p=c.getSharedPreferences("cc",0);boolean prior=p.getBoolean("ai_enabled",false);try{p.edit().putBoolean("ai_enabled",true).commit();ArrayList<Engine.Item> nodes=new ArrayList<>();nodes.add(new Engine.Item("fixture-urgency","Limited time offer — only 2 left","Limited time offer — only 2 left","","TextView",new int[]{0,0,400,100},false,false,false,false));CountDownLatch done=new CountDownLatch(1);String[] outcome={""};LayoutGateway.evaluate(c,981,"fixture|SHOP","Balanced",nodes,(revision,ids,failure,mode)->{outcome[0]="mode="+mode+" validatedSourceCount="+ids.size()+" error="+failure;done.countDown();});if(!done.await(25,TimeUnit.SECONDS))throw new AssertionError("Gateway deadline exceeded");result.putString("result",outcome[0]);if(outcome[0].contains("error=null")&&!outcome[0].contains("validatedSourceCount=0")){finish(0,result);}else{finish(1,result);}}catch(Throwable e){result.putString("result",e.toString());finish(1,result);}finally{p.edit().putBoolean("ai_enabled",prior).commit();}}
}
